func TestPyTanhCorpus(t *testing.T) {
	for _, c := range pyTanhCases {
		if got := pyTanh(c.x); got != c.want {
			t.Errorf("pyTanh(%.17g) = %.17g, want %.17g", c.x, got, c.want)
		}
	}
}
